function titleCase(s){return s.replace(/^./,c=>c.toUpperCase())}
function menuButton(action,label,iconName,value='',css=''){return `<button class="${css}" data-action="${action}" data-value="${esc(value)}">${icons(iconName)}${esc(label)}</button>`}
function secondsText(s){const v=Math.max(0,Number(s)||0);return `00:${v.toFixed(2).padStart(5,'0')}`}
function displayBoard(){return state.board}
function boardSoundList(){const search=state.search.toLowerCase().trim();let ls=state.sounds;if(state.board==='Office')ls=ls.filter(x=>['bruh','cry-meme','airhorn','red-sun','troll','faaah'].includes(x.id)||x.id.startsWith('new-'));if(state.board==='Work')ls=ls.filter(x=>['faaah','bruh','scooby','airhorn','that-one','metal-pipe'].includes(x.id)||x.id.startsWith('new-'));if(state.board==='Memes')ls=ls.filter(x=>!['red-sun','airhorn','metal-pipe'].includes(x.id));return ls.filter(x=>x.name.toLowerCase().includes(search))}
function currentImage(s){return s.artData? s.artData: `assets/${s.file||'yippee.png'}`}
function renderStatus(){return `<header class="statusbar"><span>16:12</span><div class="status-right"><span>▂▄▆</span><span>◆</span><span>◕</span><span class="battery">90</span></div></header>`}
function navbar(){const tabs=[['board','board','BOARD'],['editor','editor','EDITOR'],['library','library','LIBRARY']];return `<nav class="navbar" aria-label="Main navigation">${tabs.map(([page,icon,label])=>`<button class="nav-tab ${state.page===page||state.activeCreation&&page==='editor'||state.page==='settings'&&page===state.settingsOrigin?'active':''}" data-action="navigate" data-value="${page}" aria-label="${label}">${icons(icon)}<span>${label}</span></button>`).join('')}</nav>`}
function settingsMenu(){if(state.menu!=='settings')return '';return `<div class="popup-menu settings-menu" role="menu">${menuButton('openSettings','Playback & settings','gear')}${menuButton('themeSheet','Choose theme','spark')}${menuButton('newBoard','New board','plus')}${menuButton('demoHelp','Prototype notes','file')}</div>`}
function boardMenu(){if(state.menu!=='board')return '';return `<div class="popup-menu board-list-menu" role="menu">${state.boards.map(x=>`<button data-action="selectBoard" data-value="${esc(x)}" class="${state.board===x?'selected':''}">${icons('controller')}${esc(x)} ${state.board===x?icons('check','small'):''}</button>`).join('')}${menuButton('newBoard','Create new board','plus')}</div>`}
function padMenu(sound){if(!state.edit||state.menu!==`pad:${sound.id}`)return '';return `<div class="popup-menu pad-action-menu" role="menu">${menuButton('replace','Replace sound','replace',sound.id)}${menuButton('renameSound','Rename','pencil',sound.id)}${menuButton('move','Move to board','swap',sound.id)}${menuButton('clipSettings','Playback options','music',sound.id)}${menuButton('clear','Clear pad','trash',sound.id,'danger')}</div>`}
function quickMenu(){if(state.menu!=='quick')return '';return `<div class="popup-menu pad-action-menu align-left" role="menu">${menuButton('setQuick','Record device audio','device','device')}${menuButton('setQuick','Record microphone','mic','record')}${menuButton('setQuick','Import audio or video','file','file')}${menuButton('setQuick','Open library','library','library')}</div>`}
function padHtml(s){return `<div class="sound-pad" data-color="${s.color%15}" style="--pad-color:${gradients[s.color%gradients.length]}"><button class="pad-main" data-action="playSound" data-value="${esc(s.id)}" aria-label="Play ${esc(s.name)}"><img class="pad-image" src="${esc(currentImage(s))}" alt=""/><span class="pad-label">${esc(s.name)}</span></button><div class="pad-progress" data-pad-progress="${esc(s.id)}" aria-hidden="true"><span class="pad-progress-fill"></span></div>${state.edit?`<button class="pad-menu-trigger" data-action="padMenu" data-value="${esc(s.id)}" aria-label="More options for ${esc(s.name)}">${icons('more')}</button>${padMenu(s)}`:''}</div>`}
function gridSpec(){return state.boardGrid[state.board]||'4x4'}
function boardNavigationMode(){return state.boardNavigation[state.board]||'pages'}
function boardPageInfo(){
  const slots=gridSpec()==='3x4'?12:16;
  const perPage=slots-1; // In pagination, Quick Add occupies slot 1 on EACH page.
  const all=boardSoundList();
  const pageCount=Math.max(1,Math.ceil(all.length/perPage));
  const page=Math.max(0,Math.min(pageCount-1,state.boardPages[state.board]||0));
  state.boardPages[state.board]=page;
  return {slots,perPage,all,pageCount,page,shown:all.slice(page*perPage,(page+1)*perPage)};
}
function boardScrollInfo(){
  const slots=gridSpec()==='3x4'?12:16;
  const all=boardSoundList();
  // Quick Add occupies slot 1 ONLY ONCE in continuous scroll.
  // The initial batch fills four rows. Subsequent batches add four complete rows.
  const initialCount=slots-1;
  const previous=state.boardLoaded[state.board];
  const loaded=Math.min(all.length,Math.max(initialCount,previous??initialCount));
  state.boardLoaded[state.board]=loaded;
  return {slots,all,loaded,hasMore:loaded<all.length,shown:all.slice(0,loaded)};
}
function boardScreen(){
 const quickLabel={device:'Record device audio',record:'Record voice',file:'Import file',library:'Open library'}[state.quickAction];
 const layout=gridSpec(),mode=boardNavigationMode();
 const p=mode==='scroll'?boardScrollInfo():boardPageInfo();
 return `<div class="screen"><div class="brand-row"><div class="brand">Stimmyz<span class="brand-spark">✦</span></div><div class="row-relative"><button class="icon-btn brand-more" data-action="settingsMenu" aria-label="More app options">${icons('more','large')}</button>${settingsMenu()}</div></div><div class="subheading">Soundboard</div>
 <div class="board-actions"><div class="row-relative" style="flex:1;min-width:0"><button class="selector" data-action="boardMenu" aria-label="Choose board">${icons('controller','controller')}<span class="selector-label">${esc(displayBoard())}</span>${icons('chevron','small')}</button>${boardMenu()}</div><button class="outline-btn" data-action="editBoard">${icons(state.edit?'check':'pencil','small')} ${state.edit?'Done editing':'Edit board'}</button></div>
 <div class="search-field">${icons('search')}<input type="search" placeholder="Search soundbites..." aria-label="Search soundbites" id="search-board" value="${esc(state.search)}"/></div>
 ${Object.keys(state.soundSessions).length?`<div class="live-playback-strip"><span>${icons('music','small')} ${Object.keys(state.soundSessions).length} sound${Object.keys(state.soundSessions).length>1?'s':''} playing</span><button data-action="stopAll">${icons('stop','small')} Stop all</button></div>`:''}
 ${state.edit?`<div class="board-edit-panel"><div class="board-edit-heading">${icons('pencil','small')} Edit board · ${esc(state.board)}</div><div class="board-edit-row"><span>Grid size</span><div class="grid-size-control" role="group" aria-label="Board grid size"><button class="grid-size-option ${layout==='3x4'?'active':''}" data-action="setGrid" data-value="3x4" aria-pressed="${layout==='3x4'}">3 × 4</button><button class="grid-size-option ${layout==='4x4'?'active':''}" data-action="setGrid" data-value="4x4" aria-pressed="${layout==='4x4'}">4 × 4</button></div></div><div class="board-edit-row"><span>More sounds</span><div class="grid-size-control" role="group" aria-label="Board navigation mode"><button class="grid-size-option ${mode==='pages'?'active':''}" data-action="setBoardNavigation" data-value="pages" aria-pressed="${mode==='pages'}">Pages</button><button class="grid-size-option ${mode==='scroll'?'active':''}" data-action="setBoardNavigation" data-value="scroll" aria-pressed="${mode==='scroll'}">Scroll</button></div></div><label class="board-overlap-row"><span>Allow overlapping sounds</span><input type="checkbox" data-setting="boardOverlap" ${boardOverlapEnabled()?'checked':''}/></label><small>${mode==='pages'?'Pages show 4 rows at a time. Quick Add stays first on every page.':'Keep scrolling to load more sounds automatically. Quick Add stays first at the top.'} Applies only to this board.</small></div>`:''}
 <div class="grid-wrap" data-grid="${layout}" data-navigation="${mode}" aria-label="${layout} soundboard grid">${`<div class="sound-pad quick"><button class="quick-button" data-action="quickAdd" aria-label="Quick add: ${esc(quickLabel)}">${icons('plus')}<strong>Quick add</strong><span>${esc(quickLabel)}</span></button>${state.edit?`<button class="quick-arrow" data-action="quickMenu" aria-label="Configure quick add">${icons('chevron')}</button>`:''}${quickMenu()}</div>`}${p.shown.map(padHtml).join('')}</div>
 ${p.all.length===0?`<div class="empty-state">No sounds match your search.</div>`:''}
 ${mode==='pages'&&p.pageCount>1?`<div class="board-pagination"><button data-action="boardPage" data-value="${p.page-1}" ${p.page===0?'disabled':''} aria-label="Previous soundboard page">${icons('arrow','small')}</button><span>Page ${p.page+1} of ${p.pageCount}</span><button data-action="boardPage" data-value="${p.page+1}" ${p.page===p.pageCount-1?'disabled':''} aria-label="Next soundboard page">${icons('arrow-right','small')}</button></div>`:''}
 ${mode==='scroll'&&p.all.length>p.slots-1?`<div class="board-load-region" aria-live="polite"><span class="board-load-count">${p.loaded} of ${p.all.length} sounds</span>${p.hasMore?`<button data-action="loadMoreSounds" class="board-load-more">Load more sounds ${icons('chevron','small')}</button><div class="board-scroll-sentinel" data-scroll-sentinel="true" aria-hidden="true"></div>`:`<span class="board-load-end">All sounds loaded</span>`}</div>`:''}
 </div>`;
}
function prefToggle(name,title,desc,checked){return `<label class="settings-toggle-row"><span class="settings-toggle-copy"><strong>${title}</strong><small>${desc}</small></span><input type="checkbox" class="settings-toggle-input" data-setting="${name}" ${checked?'checked':''} aria-label="${title}"><span class="settings-switch" aria-hidden="true"></span></label>`}
function prefSelect(name,title,desc,value,options){return `<div class="setting-select-block"><label for="setting-${name}"><strong>${title}</strong><small>${desc}</small></label><select id="setting-${name}" data-setting="${name}" class="settings-select">${options.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select></div>`}
function settingsScreen(){const pref=state.playback;return `<div class="screen settings-screen"><div class="settings-page-header"><button class="settings-back" data-action="closeSettings" aria-label="Back to ${esc(state.settingsOrigin)}">${icons('arrow')}</button><div><div class="settings-kicker">MAKE IT YOURS</div><h1>Settings <span class="accent-spark">✦</span></h1></div></div>
<section class="settings-section"><div class="settings-section-title">${icons('music')}<div><strong>Playback</strong><small>Just the essentials</small></div></div>
<div class="volume-control"><div class="setting-topline"><label for="master-volume">Master volume</label><output id="master-readout">${pref.master}%</output></div><input id="master-volume" type="range" min="0" max="100" step="5" value="${pref.master}" data-setting="master" class="settings-slider"/><small>Adjust soundboard loudness without changing your phone volume.</small></div>
${prefToggle('background','Continue playback in background','Keep clips playing when you switch apps (only when supported by Android build).',pref.background)}
</section>
<section class="settings-section"><div class="settings-section-title">${icons('spark')}<div><strong>Appearance</strong><small>Choose your theme</small></div></div><button class="settings-link" data-action="themeSheet"><span>${icons('spark')} Theme <small>${esc(state.theme)}</small></span>${icons('arrow-right')}</button></section>
<section class="settings-section"><div class="settings-section-title">${icons('file')}<div><strong>Backup & restore</strong><small>Keep sounds and layouts when switching phones</small></div></div><div class="settings-pair"><button class="settings-soft-btn" data-action="exportBackup">${icons('upload')} Export backup</button><button class="settings-soft-btn" data-action="importBackup">${icons('file')} Import backup</button></div></section>
<section class="settings-section"><div class="settings-section-title">${icons('file')}<div><strong>About</strong><small>App version, privacy and licenses</small></div></div><button class="settings-link" data-action="demoHelp"><span>About Stimmyz</span>${icons('arrow-right')}</button></section>
<div class="settings-footer-note">Prototype only: settings are simulated. Astra must connect native playback and persistence; do not ship unimplemented background audio.</div></div>`}
function editorScreen(){return `<div class="screen"><div class="editor-head"><h1>Make a sound <span class="accent-spark">✦</span></h1><p>Capture the moment. Turn it into a button.</p></div><section class="card device-capture-card"><div class="capture-kicker"><span class="capture-dot"></span> RECORD WHAT’S PLAYING</div><div class="capture-hero-icon">${icons('device-audio','xlarge')}</div><h2>Record device audio</h2><div class="capture-steps"><span>Start</span>${icons('arrow-right','tiny')}<span>Play moment</span>${icons('arrow-right','tiny')}<span>Stop & trim</span></div><button class="gradient-btn device-primary" data-action="deviceRecord">Record device audio</button><small class="capture-restriction">Works with compatible apps · Android will ask for permission</small></section><div class="secondary-methods-label">OTHER WAYS TO ADD A SOUND</div><button class="secondary-method" data-action="record"><span class="secondary-method-icon">${icons('mic')}</span><span><strong>Record your voice</strong><small>Use your microphone</small></span>${icons('arrow-right','small')}</button><button class="secondary-method" data-action="chooseFile"><span class="secondary-method-icon">${icons('file')}</span><span><strong>Import audio or video</strong><small>Choose a file already on your phone</small></span>${icons('arrow-right','small')}</button>${state.build==='personal'?`<section class="card editor-link"><div class="section-title">${icons('link')} YouTube URL · personal build only</div><p class="hint">Not available in the Play release. The optional device recorder works independently of this feature.</p><div class="link-row"><input class="textbox" id="youtube-link" placeholder="https://youtu.be/..." aria-label="YouTube link"><button class="soft-btn" data-action="youtubeDemo">Load (demo)</button></div></section>`:''}<p class="demo-badge">Interactive design demo · capture and media processing are simulated</p></div>`}
function libraryMore(sound){if(state.menu!==`lib:${sound.id}`)return '';return `<div class="popup-menu library-action-menu" role="menu">${menuButton('playSound','Play','play',sound.id)}${menuButton('renameSound','Rename','pencil',sound.id)}${menuButton('changeArtwork','Change artwork','image',sound.id)}${menuButton('clipSettings','Playback options','music',sound.id)}${menuButton('addBoard','Add to board','plus',sound.id)}${menuButton('delete','Delete','trash',sound.id,'danger')}</div>`}
function libraryScreen(){let list=state.sounds.filter(x=>x.saved && x.name.toLowerCase().includes(state.librarySearch.toLowerCase()));if(state.sortAZ)list=[...list].sort((a,b)=>a.name.localeCompare(b.name));return `<div class="screen"><div class="library-header">${icons('library')}<div><h1>Your library <span class="accent-spark">✦</span></h1><p>Your clips, ready to play offline.<br/>Add any sound to your boards.</p></div></div><button class="gradient-btn library-primary" data-action="deviceRecord">Record device audio</button><div class="library-search-row"><div class="search-field">${icons('search')}<input type="search" id="search-library" value="${esc(state.librarySearch)}" placeholder="Search sounds..." aria-label="Search library"/></div><button class="sort-btn" data-action="sortLibrary" aria-label="Change library sorting">${icons('sort')}</button></div><div class="count">${list.length} / 1000 soundbites</div><div class="library-list">${list.map(s=>`<div class="library-row"><div class="lib-thumb" style="background:${gradients[s.color%15]}"><img src="${esc(currentImage(s))}" alt=""/></div><div class="lib-body"><strong>${esc(s.name)}</strong><small>${s.duration} · Saved offline</small></div><button class="round-play" data-action="playSound" data-value="${esc(s.id)}" aria-label="Play ${esc(s.name)}">${icons('play')}</button><button class="icon-btn lib-more" data-action="libraryMenu" data-value="${esc(s.id)}" aria-label="More options for ${esc(s.name)}">${icons('more')}</button>${libraryMore(s)}</div>`).join('')}</div><button class="new-sound" data-action="beginCreate"><span class="circle-plus">${icons('plus')}</span><strong>More ways to add a sound</strong><small>Record voice · Import file</small></button></div>`}
function stepper(){return `<div class="stepper">${[['source','Source'],['trim','Trim'],['details','Details']].map(([step,name],i)=>`<div class="step-item ${state.creationStep===step?'current':(step==='source'&&state.creationStep!=='source'||step==='trim'&&state.creationStep==='details')?'done':''}"><div class="circle">${(step==='source'&&state.creationStep!=='source'||step==='trim'&&state.creationStep==='details')?icons('check','tiny'):i+1}</div><span>${name}</span></div>`).join('')}</div>`}
function createFlowSource(){if(state.recording){const isDevice=state.captureMode==='device';return `<h2 class="detail-title">${isDevice?'Recording device audio':'Recording your voice'}</h2><section class="card capture-in-progress"><div class="live-pill"><span class="live-indicator"></span> DEMO RECORDING</div><div class="capture-hero-icon">${icons(isDevice?'device-audio':'mic','xlarge')}</div><h3>${isDevice?'Capture audio from another app':'Microphone is recording'}</h3><p>${isDevice?'In the real Android app, switch to an app that permits playback capture and play your clip. Tap Stop in the capture notification to return for trimming.':'Say your quote, make the sound, or record a real-world moment.'}</p><div class="rec-wave">${Array.from({length:23},(_,i)=>`<i style="height:${18+Math.abs(Math.sin(i*1.6)*44)}px"></i>`).join('')}</div><div class="sim-note">This is a visual prototype: no actual device or microphone audio is recorded.</div></section><div class="flow-spacer"></div><button class="record-btn flow-bottom" data-action="${isDevice?'deviceRecord':'record'}">${icons('stop')} Stop & trim</button><button class="soft-btn flow-bottom" data-action="cancelCreate">Discard</button>`};return `<h2 class="detail-title">How would you like to capture it?</h2><p class="source-intro">Try capturing audio playing in a compatible app.</p><button class="flow-source-option featured" data-action="deviceRecord"><span class="round-icon">${icons('device-audio')}</span><span><strong>Record device audio <em>FEATURED</em></strong><small>Play a moment in another app, then trim</small></span>${icons('arrow-right','small')}</button><p class="device-source-note">For compatible apps only · permission required per session</p><button class="flow-source-option" data-action="record"><span class="round-icon">${icons('mic')}</span><span><strong>Record your voice</strong><small>Use the microphone</small></span></button><button class="flow-source-option" data-action="chooseFile"><span class="round-icon">${icons('file')}</span><span><strong>Import audio or video</strong><small>Choose an existing file</small></span></button>${state.build==='personal'?`<button class="flow-source-option" data-action="youtubeDemo"><span class="round-icon">${icons('link')}</span><span><strong>Use a YouTube link · dev only</strong><small>Personal development preview</small></span></button>`:''}<div class="flow-spacer"></div><button class="soft-btn flow-bottom" data-action="cancelCreate">Cancel</button>`}
const waveHeights=Array.from({length:64},(_,i)=>Math.round(14+Math.abs(Math.sin(i*1.92)*33)+Math.abs(Math.sin(i*.41)*17)));
function waveform(){let l=state.start/state.total*100,r=state.end/state.total*100,p=state.playhead/state.total*100;return `<div class="waveform" id="waveform" aria-label="Interactive waveform; drag the start and end handles"><div class="wave-bars">${waveHeights.map(h=>`<i style="height:${h}%"></i>`).join('')}</div><div class="wave-selection" id="wave-selection" style="left:${l}%;width:${r-l}%"><div class="bar-highlighter"></div></div><div class="wave-played" id="wave-played" style="left:${l}%;width:${Math.max(0,p-l)}%"></div><div class="wave-playhead" id="wave-playhead" style="left:${p}%"></div><button class="wave-handle" data-handle="start" style="left:${l}%" aria-label="Drag clip start"></button><button class="wave-handle" data-handle="end" style="left:${r}%" aria-label="Drag clip end"></button></div>`}
function fineTune(){return `<div class="fine-tune"><button class="fine-head" data-action="toggleFine">Fine tune <span>(optional) ${icons('chevron','small')}</span></button>${state.fine?`<div class="fine-grid"><strong>Start</strong><code id="fine-start">${secondsText(state.start)}</code>${[-1,-.1,.1,1].map(n=>`<button data-action="fineStart" data-value="${n}">${n>0?'+':''}${Math.abs(n)<1?(n*1000)+'ms':n+'s'}</button>`).join('')}<strong>End</strong><code id="fine-end">${secondsText(state.end)}</code>${[-1,-.1,.1,1].map(n=>`<button data-action="fineEnd" data-value="${n}">${n>0?'+':''}${Math.abs(n)<1?(n*1000)+'ms':n+'s'}</button>`).join('')}</div>`:''}</div>`}
function createFlowTrim(){return `<div class="trim-source"><div class="trim-source-icon">🔊</div><div class="trim-source-text"><strong>${esc(state.sourceName)}</strong><small>${secondsText(state.total)} total · Up to 60 seconds</small></div></div><div class="wave-card">${waveform()}<div class="times"><span id="time-start">${secondsText(state.start)}</span><span id="time-selected">${secondsText(state.end-state.start)} selected</span><span id="time-end">${secondsText(state.end)}</span></div><div class="preview-transport"><button class="preview-btn" id="trim-preview-toggle" data-action="previewTrim" aria-pressed="${state.previewPlaying}">${icons(state.previewPlaying?'pause':'play')} ${state.previewPlaying?'Pause':'Play'} preview</button><button class="preview-loop ${state.previewLoop?'active':''}" data-action="previewLoop" aria-pressed="${state.previewLoop}" aria-label="Loop selected clip" title="Loop selected clip">${icons('repeat','small')} Loop</button></div><div class="preview-progress" role="progressbar" aria-label="Selection playback progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round((state.playhead-state.start)/(state.end-state.start)*100)}"><div class="preview-progress-fill" id="preview-progress-fill" style="width:${Math.max(0,Math.min(100,(state.playhead-state.start)/(state.end-state.start)*100))}%"></div></div><div class="preview-times"><span id="preview-elapsed">${secondsText(state.playhead-state.start)}</span><span id="preview-total">${secondsText(state.end-state.start)}</span></div><p class="preview-disclaimer">UI playback simulation only; Android must use real audio timestamps.</p></div>${fineTune()}<div class="selection-info">Drag both waveform handles to select the moment. Fine tune is optional.</div><div class="flow-spacer"></div><button class="gradient-btn flow-bottom" data-action="nextDetails">Next →</button>`}
function previewArt(){if(state.artUploaded)return `<img src="${state.artUploaded}" alt="Uploaded artwork preview"/>`;if(state.artMode==='default')return icons('music','xlarge');return `<img src="assets/${esc(state.artChoice)}" alt="Selected artwork preview"/>`}
function createFlowDetails(){return `<h2 class="detail-title">Make it yours <span class="accent-spark">✦</span></h2><div class="artwork-summary"><div class="artwork-preview">${previewArt()}</div><div><strong>Optional artwork</strong><p>Choose a picture for your pad or keep the default icon.</p></div></div><label class="fieldlabel" for="sound-name">SOUNDBITE NAME</label><input id="sound-name" class="textbox" maxlength="100" value="${esc(state.saveName)}" aria-label="Soundbite name"/><div class="details-options"><button class="art-option ${state.artMode==='default'?'active':''}" data-action="artDefault">${icons('music')} Default</button><button class="art-option" data-action="artGallery">${icons('image')} Gallery</button><button class="art-option ${state.artMode==='search'?'active':''}" data-action="artSearch">${icons('search')} Search</button></div>${state.artMode==='search'?`<p class="detail-hint">Online artwork search requires a licensed API. Results below are UI placeholders only.</p><input class="textbox" id="art-query" placeholder="Search, e.g. reaction cat" value="${esc(state.onlineQuery)}"/><div class="art-search-grid">${['😸','🤖','💜','🌈'].map((x,i)=>`<button data-action="selectOnlineArt" data-value="${i}" aria-label="Choose sample sticker ${i+1}">${x}</button>`).join('')}</div>`:''}<p class="detail-hint">Your clip and optional artwork will be stored on the device. You can skip artwork.</p><div class="flow-spacer"></div><button class="gradient-btn flow-bottom" data-action="saveSound">Save soundbite</button>`}
function createScreen(){return `<div class="screen create-screen"><div class="flow-header"><button class="icon-btn" data-action="${state.creationStep==='source'?'cancelCreate':'flowBack'}" aria-label="Back">${icons(state.creationStep==='source'?'close':'arrow','large')}</button><h1>Create a sound</h1><span style="width:36px"></span></div>${stepper()}${state.creationStep==='source'?createFlowSource():state.creationStep==='trim'?createFlowTrim():createFlowDetails()}</div>`}
function clipSettingsModal(sound){if(!sound)return '';const c=state.clipSettingsDraft||{gain:100,repeat:'once'};const db=c.gain===0?'Muted':c.gain===100?'Original level':`${(20*Math.log10(c.gain/100)).toFixed(1)} dB`;
 return `<div class="modal-scrim"><div class="dialog clip-settings-dialog" role="dialog" aria-modal="true" aria-label="Playback options for ${esc(sound.name)}"><div class="clip-dialog-head"><div class="clip-dialog-icon">${icons('music')}</div><div><span class="settings-kicker">SOUND PLAYBACK</span><h2>${esc(sound.name)}</h2></div></div>
 <div class="volume-control"><div class="setting-topline"><label for="clip-gain">Sound volume &amp; boost</label><output id="clip-volume-readout">${c.gain}%</output></div><input id="clip-gain" type="range" min="0" max="200" step="5" value="${c.gain}" class="settings-slider" data-setting="clipGain"/><div class="gain-tick-labels"><span>0% · mute</span><span>100% · original</span><span>200% · boost</span></div><small id="gain-db-readout">${db}</small><p class="setting-note">Above 100% applies digital amplification, not extra speaker power. Native implementation must apply safe peak limiting and prevent clipping, including when sounds overlap.</p></div>
 ${prefSelect('clipRepeat','Repeat','Choose what happens when this sound ends.',c.repeat,[['once','Play once'],['loop','Loop until stopped'],['three','Repeat 3 times']])}
 <div class="row"><button class="soft-btn" data-action="closeDialog">Cancel</button><button class="gradient-btn" data-action="saveClipSettings" data-value="${esc(sound.id)}">Save options</button></div></div></div>`}
function modal(){if(state.dialog?.type==='clipSettings')return clipSettingsModal(state.sounds.find(s=>s.id===state.dialog.id));if(state.dialog==='themes')return `<div class="floating-theme"><div class="theme-sheet"><h2>Choose your mood ✦</h2><p>Six approved Stimmyz themes. Your sound pad artwork and sizing stay the same.</p><div class="theme-grid">${Object.keys(themeSwatches).map(x=>`<button class="theme-choice ${state.theme===x?'active':''}" data-action="theme" data-value="${x}"><span class="theme-blob" style="background:${themeSwatches[x]}"></span>${x}</button>`).join('')}</div><button class="soft-btn" style="width:100%" data-action="closeDialog">Done</button></div></div>`;
if(!state.dialog)return '';
let d=state.dialog;let s=state.sounds.find(x=>x.id===d.id);let title=d.type==='rename'?'Rename sound':d.type==='newBoard'?'Create board':d.type==='clear'?'Clear sound pad?':d.type==='delete'?'Delete sound?':d.type==='move'?'Move sound to board':d.type==='addBoard'?'Add sound to board':'Notice';return `<div class="modal-scrim"><div class="dialog" role="dialog" aria-modal="true"><h2>${title}</h2>${d.type==='rename'||d.type==='newBoard'?`<input class="textbox" id="dialog-field" value="${d.type==='rename'?esc(s?.name||''):''}" placeholder="Name"/>`:''}${d.type==='delete'||d.type==='clear'?`<p class="detail-hint">${esc(s?.name||'This clip')} will ${d.type==='delete'?'be deleted from the demo library':'be removed from this board'}. This demonstration can be reset by reloading.</p>`:''}${d.type==='move'||d.type==='addBoard'?`<div class="theme-grid" style="grid-template-columns:1fr 1fr">${state.boards.map(x=>`<button class="theme-choice" data-action="confirmBoardMove" data-value="${esc(x)}">${esc(x)}</button>`).join('')}</div>`:''}<div class="row"><button class="soft-btn" data-action="closeDialog">Cancel</button>${!['move','addBoard'].includes(d.type)?`<button class="gradient-btn" data-action="confirmDialog">${d.type==='delete'||d.type==='clear'?'Confirm':'Save'}</button>`:''}</div></div></div>`}
let padFrame=null,padPrevMs=null;
function boardOverlapEnabled(){return state.boardPlayback[state.board]===true}
function padDuration(sound){const a=(sound.duration||'00:01').split(':').map(Number);return Math.max(.2,(a.length===2?a[0]*60+a[1]:a[0])||1)}
function padRepeatMode(sound){return sound.repeat||'once'}
function syncPadProgress(){document.querySelectorAll('[data-pad-progress]').forEach(el=>{const id=el.dataset.padProgress;const session=state.soundSessions[id];const fill=el.querySelector('.pad-progress-fill');const pad=el.closest('.sound-pad');if(!session){el.classList.remove('is-visible');pad?.classList.remove('is-playing');return;}el.classList.add('is-visible');pad?.classList.toggle('is-playing',!session.paused);fill.style.width=(100*Math.min(1,session.position/session.duration))+'%';pad?.setAttribute('aria-label',`${Math.round(100*session.position/session.duration)}% played`);});}
function padAnimation(now){if(padPrevMs!==null){let delta=Math.min((now-padPrevMs)/1000,.14);for(const [id,x] of Object.entries(state.soundSessions)){if(x.paused)continue;x.position+=delta;if(x.position>=x.duration){x.rounds++;if(x.repeat==='loop'||(x.repeat==='three'&&x.rounds<3))x.position%=x.duration;else delete state.soundSessions[id];}}}padPrevMs=now;syncPadProgress();padFrame=Object.keys(state.soundSessions).length?requestAnimationFrame(padAnimation):null;if(!padFrame)padPrevMs=null;}
function triggerPad(sound){if(!sound)return;const id=sound.id, existing=state.soundSessions[id];
if(!boardOverlapEnabled())state.soundSessions={};
state.soundSessions[id]={position:0,duration:padDuration(sound),paused:false,repeat:padRepeatMode(sound),rounds:0};
if(!padFrame){padPrevMs=null;padFrame=requestAnimationFrame(padAnimation);}syncPadProgress();}
function stopPads(){state.soundSessions={};if(padFrame!==null)cancelAnimationFrame(padFrame);padFrame=null;padPrevMs=null;syncPadProgress()}
function syncPreviewVisual(){
  const duration=Math.max(.001,state.end-state.start);
  const elapsed=Math.min(duration,Math.max(0,state.playhead-state.start));
  const frac=Math.min(1,elapsed/duration);
  const wave=document.getElementById('waveform');
  if(wave){const head=wave.querySelector('#wave-playhead');if(head)head.style.left=(state.playhead/state.total*100)+'%';
    const played=wave.querySelector('#wave-played');if(played){played.style.left=(state.start/state.total*100)+'%';played.style.width=((state.playhead-state.start)/state.total*100)+'%';}}
  const bar=document.getElementById('preview-progress-fill');if(bar)bar.style.width=(frac*100)+'%';
  const track=document.querySelector('.preview-progress');if(track)track.setAttribute('aria-valuenow',String(Math.round(frac*100)));
  const elapsedEl=document.getElementById('preview-elapsed');if(elapsedEl)elapsedEl.textContent=secondsText(elapsed);
  const totalEl=document.getElementById('preview-total');if(totalEl)totalEl.textContent=secondsText(duration);
  const toggle=document.getElementById('trim-preview-toggle');if(toggle){toggle.innerHTML=icons(state.previewPlaying?'pause':'play')+' '+(state.previewPlaying?'Pause':'Play')+' preview';toggle.setAttribute('aria-pressed',String(state.previewPlaying));}
}
function pausePreview(){state.previewPlaying=false;previewPreviousMs=null;if(previewFrame!==null)cancelAnimationFrame(previewFrame);previewFrame=null;syncPreviewVisual()}
function previewAnimationStep(now){if(!state.previewPlaying)return;
  if(previewPreviousMs!==null)state.playhead+=(now-previewPreviousMs)/1000;
  previewPreviousMs=now;
  if(state.playhead>=state.end){if(state.previewLoop){state.playhead=state.start+((state.playhead-state.start)%(state.end-state.start));}else{state.playhead=state.end;pausePreview();return;}}
  syncPreviewVisual();previewFrame=requestAnimationFrame(previewAnimationStep);
}
function togglePreview(){
 if(state.previewPlaying){pausePreview();return;}
 if(state.playhead>=state.end-0.001||state.playhead<state.start)state.playhead=state.start;
 state.previewPlaying=true;previewPreviousMs=null;syncPreviewVisual();previewFrame=requestAnimationFrame(previewAnimationStep);
}
function resetPreview(){pausePreview();state.playhead=state.start;syncPreviewVisual()}
function render(preserveScroll=true){if(boardLazyObserver){boardLazyObserver.disconnect();boardLazyObserver=null;}const oldScroll=preserveScroll?app.querySelector('.screen')?.scrollTop||0:0;app.dataset.theme=state.theme;app.innerHTML=renderStatus()+(state.activeCreation?createScreen():state.page==='board'?boardScreen():state.page==='editor'?editorScreen():state.page==='settings'?settingsScreen():libraryScreen())+(state.activeCreation?'':navbar())+modal()+(state.toast?`<div class="toast" role="status">${esc(state.toast)}</div>`:'');const screen=app.querySelector('.screen');if(screen&&preserveScroll)screen.scrollTop=oldScroll;themeSelect.value=state.theme;buildSelect.value=state.build;document.querySelectorAll('[data-preview-page]').forEach(el=>el.classList.toggle('selected',el.dataset.previewPage===(state.activeCreation?state.creationStep:state.page)));attachWave();syncPadProgress();attachBoardLazyLoader();}
function loadMoreSounds(){
 if(state.page!=='board'||boardNavigationMode()!=='scroll')return;
 const initial=gridSpec()==='3x4'?12:16;
 const total=boardSoundList().length;
 const current=state.boardLoaded[state.board]??(initial-1);
 if(current>=total)return;
 // A second batch has all rows available; don't repeat Quick Add.
 state.boardLoaded[state.board]=Math.min(total,current+initial);
 render(true);
}
function attachBoardLazyLoader(){
 const sentinel=app.querySelector('[data-scroll-sentinel]');
 const screen=app.querySelector('.screen');
 if(!sentinel||!screen||typeof IntersectionObserver==='undefined')return;
 boardLazyObserver=new IntersectionObserver(entries=>{
  if(entries.some(entry=>entry.isIntersecting))loadMoreSounds();
 },{root:screen,rootMargin:'0px 0px 80px 0px',threshold:0.01});
 boardLazyObserver.observe(sentinel);
}
function notify(message){state.toast=message;render();clearTimeout(notify.timeout);notify.timeout=setTimeout(()=>{state.toast='';render()},2500)}
function startCreate(step='source'){state.activeCreation=true;state.creationStep=step;state.menu=null;state.fine=false;state.artMode='default';state.saveName=state.sourceName;render(false)}
function startTrim(name){state.sourceName=name||'New recording';state.saveName=state.sourceName;state.total=9.35;state.start=2.52;state.end=5;state.playhead=state.start;state.previewPlaying=false;startCreate('trim')}
function closeMenus(){state.menu=null}
function showDialog(type,id){state.menu=null;state.dialog={type,id};render()}
function processAction(action,value,button){const sound=state.sounds.find(x=>x.id===value);switch(action){
 case 'navigate':pausePreview();if(!state.playback.background)stopPads();state.page=value;state.activeCreation=false;state.menu=null;state.edit=false;state.search='';state.librarySearch='';render(false);break;
 case 'openSettings':if(!state.playback.background)stopPads();state.settingsOrigin=state.page==='settings'?state.settingsOrigin:state.page;state.page='settings';state.menu=null;render(false);break;
 case 'closeSettings':state.page=state.settingsOrigin||'board';state.menu=null;render(false);break;
 case 'settingsMenu':state.menu=state.menu==='settings'?null:'settings';render();break;
 case 'boardMenu':state.menu=state.menu==='board'?null:'board';render();break;
 case 'selectBoard':state.board=value;state.menu=null;stopPads();render(false);break;
 case 'setGrid':if(value==='3x4'||value==='4x4'){state.boardGrid[state.board]=value;state.boardPages[state.board]=0;state.boardLoaded[state.board]=value==='3x4'?11:15;state.menu=null;render();}break;
 case 'setBoardNavigation':if(value==='pages'||value==='scroll'){state.boardNavigation[state.board]=value;state.boardPages[state.board]=0;state.boardLoaded[state.board]=gridSpec()==='3x4'?11:15;state.menu=null;render();}break;
 case 'loadMoreSounds':loadMoreSounds();break;
 case 'boardPage':state.boardPages[state.board]=Math.max(0,Number(value));stopPads();render();break;
 case 'editBoard':state.edit=!state.edit;state.menu=null;render();break;
 case 'padMenu':if(state.edit){state.menu=state.menu===`pad:${value}`?null:`pad:${value}`;render();}break;
 case 'libraryMenu':state.menu=state.menu===`lib:${value}`?null:`lib:${value}`;render();break;
 case 'quickMenu':state.menu=state.menu==='quick'?null:'quick';render();break;
 case 'setQuick':state.quickAction=value;state.menu=null;notify(`Quick Add action: ${{device:'Record device audio',record:'Record microphone',file:'Import file',library:'Library'}[value]||value}`);break;
 case 'quickAdd':if(state.edit){state.menu='quick';render()}else if(state.quickAction==='device')processAction('deviceRecord');else if(state.quickAction==='record')processAction('record');else if(state.quickAction==='file')processAction('chooseFile');else processAction('navigate','library');break;
 case 'exportBackup':notify('Preview only · Astra must implement a complete ZIP backup with audio and artwork');break;
 case 'importBackup':notify('Preview only · Astra must implement safe ZIP import/merge');break;
 case 'themeSheet':state.dialog='themes';state.menu=null;render();break;
 case 'theme':state.theme=value;state.dialog='themes';render();break;
 case 'closeDialog':state.dialog=null;render();break;
 case 'newBoard':showDialog('newBoard');break;
 case 'playSound':triggerPad(sound);render();break;
 case 'stopAll':stopPads();render();break;
 case 'replace':state.targetPad=value;startCreate('source');break;
 case 'renameSound':showDialog('rename',value);break;
 case 'clipSettings':state.clipSettingsDraft={gain:sound?.gain??100,repeat:sound?.repeat||'once'};showDialog('clipSettings',value);break;
 case 'saveClipSettings':if(sound&&state.clipSettingsDraft){sound.gain=state.clipSettingsDraft.gain;sound.repeat=state.clipSettingsDraft.repeat;}state.clipSettingsDraft=null;state.dialog=null;notify('Clip playback options saved in demo');break;
 case 'move':showDialog('move',value);break;
 case 'clear':showDialog('clear',value);break;
 case 'delete':showDialog('delete',value);break;
 case 'addBoard':showDialog('addBoard',value);break;
 case 'changeArtwork':state.targetPad=value;state.saveName=sound?.name||'Sound';state.sourceName=state.saveName;startCreate('details');break;
 case 'confirmBoardMove':state.board=value;state.dialog=null;notify(`Assigned to ${value} (UI demo)`);break;
 case 'confirmDialog':confirmDialog();break;
 case 'beginCreate':state.targetPad=null;startCreate('source');break;
 case 'chooseFile':document.getElementById('audio-input').click();break;
 case 'record':if(!state.recording){state.recording=true;state.captureMode='mic';state.dialog=null;startCreate('source')}else{state.recording=false;state.captureMode=null;startTrim('My recording')}break;
 case 'deviceRecord':if(!state.recording){state.recording=true;state.captureMode='device';state.dialog=null;startCreate('source')}else{state.recording=false;state.captureMode=null;startTrim('Device audio recording')}break;
 case 'youtubeDemo':if(state.build==='personal')startTrim('YouTube excerpt (demo)');else notify('Unavailable in the Play Store build');break;
 case 'cancelCreate':resetPreview();state.activeCreation=false;state.recording=false;state.captureMode=null;state.menu=null;render(false);break;
 case 'flowBack':resetPreview();if(state.creationStep==='details')state.creationStep='trim';else if(state.creationStep==='trim')state.creationStep='source';else state.activeCreation=false;render(false);break;
 case 'toggleFine':state.fine=!state.fine;render();break;
 case 'fineStart':resetPreview();state.start=Math.min(Math.max(state.start+Number(value),0),state.end-.1);state.playhead=state.start;render();break;
 case 'fineEnd':resetPreview();state.end=Math.min(Math.max(state.end+Number(value),state.start+.1),Math.min(state.total,state.start+60));state.playhead=state.start;render();break;
 case 'previewTrim':togglePreview();break;
 case 'previewLoop':state.previewLoop=!state.previewLoop;render();break;
 case 'nextDetails':resetPreview();state.creationStep='details';state.saveName=state.sourceName;render(false);break;
 case 'artDefault':state.artMode='default';state.artUploaded=null;render();break;
 case 'artGallery':document.getElementById('art-input').click();break;
 case 'artSearch':state.artMode='search';render();break;
 case 'selectOnlineArt':state.artMode='selected';state.artChoice=['cry-meme.png','metal-pipe.png','yippee.png','uwu.png'][Number(value)];render();break;
 case 'saveSound':resetPreview();saveSound();break;
 case 'sortLibrary':state.sortAZ=!state.sortAZ;render();notify(state.sortAZ?'Sorted A–Z':'Original library order');break;
 case 'demoHelp':state.menu=null;notify('This HTML demonstrates UI behavior. Review the handoff for Android implementation.');break;
 default:break;}}
function confirmDialog(){const d=state.dialog;if(!d)return;const inp=document.getElementById('dialog-field')?.value.trim();if(d.type==='newBoard'){if(!inp){notify('Enter a board name');return;}if(!state.boards.includes(inp))state.boards.push(inp);state.board=inp;}
if(d.type==='rename'&&inp){const s=state.sounds.find(x=>x.id===d.id);if(s)s.name=inp}
if(d.type==='delete'||d.type==='clear'){state.sounds=state.sounds.filter(x=>x.id!==d.id)}state.dialog=null;render();}
function saveSound(){const name=document.getElementById('sound-name')?.value.trim()||'New sound';if(state.targetPad){const s=state.sounds.find(x=>x.id===state.targetPad);if(s){s.name=name;if(state.artUploaded)s.artData=state.artUploaded;else if(state.artMode==='selected')s.file=state.artChoice;}state.targetPad=null}else{state.sounds.push({id:`new-${Date.now()}`,name,color:state.sounds.length%gradients.length,file:state.artChoice,duration:secondsText(state.end-state.start),artData:state.artUploaded,saved:true})}state.activeCreation=false;state.page='board';state.menu=null;state.search='';state.artUploaded=null;notify('Soundbite saved in demo · Quick Add stayed at #1')}
function attachWave(){const wave=document.getElementById('waveform');if(!wave)return;let active=null;const clamp=(v,min,max)=>Math.min(Math.max(v,min),max);const updateVisual=()=>{let sel=document.getElementById('wave-selection');if(!sel)return;sel.style.left=(state.start/state.total*100)+'%';sel.style.width=((state.end-state.start)/state.total*100)+'%';for(const h of wave.querySelectorAll('[data-handle]'))h.style.left=((h.dataset.handle==='start'?state.start:state.end)/state.total*100)+'%';let a=document.getElementById('time-start'),b=document.getElementById('time-end'),c=document.getElementById('time-selected');if(a)a.textContent=secondsText(state.start);if(b)b.textContent=secondsText(state.end);if(c)c.textContent=secondsText(state.end-state.start)+' selected';state.playhead=state.start;syncPreviewVisual()};
wave.onpointerdown=e=>{let h=e.target.closest('[data-handle]');if(!h)return;resetPreview();active=h.dataset.handle;e.preventDefault();wave.setPointerCapture(e.pointerId)};
wave.onpointermove=e=>{if(!active)return;let rect=wave.getBoundingClientRect();let sec=clamp((e.clientX-rect.left)/rect.width,0,1)*state.total;if(active==='start')state.start=clamp(sec,0,state.end-.1);else state.end=clamp(sec,state.start+.1,Math.min(state.total,state.start+60));updateVisual()};
wave.onpointerup=e=>{if(!active)return;active=null;try{wave.releasePointerCapture(e.pointerId)}catch{};render()};wave.onpointercancel=()=>{active=null;render()};}
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;const v=b.dataset.value||'';processAction(a,v,b)});
app.addEventListener('change',e=>{const el=e.target,key=el.dataset.setting;if(!key)return;
 if(key==='boardOverlap'){state.boardPlayback[state.board]=el.checked; if(!el.checked)stopPads();render();return;}
 if(key==='clipRepeat'){state.clipSettingsDraft.repeat=el.value;render();return;}
 if(key==='clipGain'||key==='master')return;
 if(key==='background'){state.playback.background=el.checked;render();return;}
});
app.addEventListener('input',e=>{const el=e.target;if(el.dataset.setting==='master'){state.playback.master=Number(el.value);document.getElementById('master-readout').textContent=el.value+'%';return;}if(el.dataset.setting==='clipGain'){state.clipSettingsDraft.gain=Number(el.value);document.getElementById('clip-volume-readout').textContent=el.value+'%';const g=Number(el.value);document.getElementById('gain-db-readout').textContent=g===0?'Muted':g===100?'Original level':(20*Math.log10(g/100)).toFixed(1)+' dB';return;}if(el.id==='search-board'){state.search=el.value;state.boardPages[state.board]=0;state.boardLoaded[state.board]=gridSpec()==='3x4'?11:15;let pos=el.selectionStart;render();const input=document.getElementById('search-board');if(input){input.focus();input.setSelectionRange(pos,pos)}}else if(el.id==='search-library'){state.librarySearch=el.value;let pos=el.selectionStart;render();const input=document.getElementById('search-library');if(input){input.focus();input.setSelectionRange(pos,pos)}}else if(el.id==='sound-name')state.saveName=el.value;else if(el.id==='art-query')state.onlineQuery=el.value});
document.getElementById('audio-input').addEventListener('change',e=>{const f=e.target.files?.[0];if(f)startTrim(f.name.replace(/\.[^.]+$/,''));e.target.value=''});
document.getElementById('art-input').addEventListener('change',e=>{let f=e.target.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{state.artUploaded=String(reader.result);state.artMode='gallery';render()};reader.readAsDataURL(f);e.target.value=''});
themeSelect.addEventListener('change',e=>{state.theme=e.target.value;render()});buildSelect.addEventListener('change',e=>{state.build=e.target.value;state.menu=null;render()});
document.querySelectorAll('[data-preview-page]').forEach(btn=>btn.addEventListener('click',()=>{const page=btn.dataset.previewPage;resetPreview();state.activeCreation=['trim','details'].includes(page);state.creationStep=state.activeCreation?page:'source';state.page=state.activeCreation?'editor':page;state.dialog=null;state.menu=null;render(false)}));
render(false);

// UI-only preview: pause when tab backgrounds, like real audio-focus loss.
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.previewPlaying)pausePreview()});
